A = list(map(int, input().split()))
expected = list(range(1, 6))
diff = [i for i in range(5) if A[i] != expected[i]]
if len(diff) == 2:
    i, j = diff
    if A[i] == expected[j] and A[j] == expected[i]:
        print("Yes")
    else:
        print("No")
else:
    print("No")

